// content.js
chrome.runtime.onMessage.addListener(function(message, sender, sendResponse) {
  if (message.action === "get_user_info") {
    // प्रयोगकर्ताको लिङ्ग, आय वर्ग र जातीयता प्राप्त गर्नुहोस्
    let user_info = {
      gender: "male",
      income_class: "middle",
      ethnicity: "white"
    };

    // प्रयोगकर्ताको लिङ्ग, आय वर्ग र जातीयताको आधारमा मूल्य उत्पन्न गर्नुहोस्
    let price = calculate_price(user_info);

    // मूल्य प्रयोगकर्तालाई पठाउनुहोस्
    sendResponse({ price: price });
  }
});

function calculate_price(user_info) {
  // प्रयोगकर्ताको लिङ्ग, आय वर्ग र जातीयताको आधारमा मूल्य उत्पन्न गर्नुहोस्
  if (user_info.gender === "male" && user_info.income_class === "middle" && user_info.ethnicity === "white") {
    return 100;
  } else if (user_info.gender === "female" && user_info.income_class === "middle" && user_info.ethnicity === "white") {
    return 90;
  } else {
    return 80;
  }
}
